class RandomizedSet:
    def __init__(self):
        self.vals = []          # for O(1) random access
        self.index = {}         # value -> position in vals

    def insert(self, val: int) -> bool:
        if val in self.index:
            return False
        self.index[val] = len(self.vals)
        self.vals.append(val)
        return True

    def remove(self, val: int) -> bool:
        if val not in self.index:
            return False
        i, last = self.index[val], self.vals[-1]
        self.vals[i] = last              # move the last element into the hole
        self.index[last] = i
        self.vals.pop()
        del self.index[val]              # delete last so removing the last element also works
        return True

    def getRandom(self) -> int:
        return random.choice(self.vals)
